import { requireRole, logout } from "./auth-service.js";
import { listReports, updateReport } from "./data-service.js";
import { LOCATIONS, escapeHTML, initLeafletMap, markerIcon, priorityClass, priorityLabel, setupPortal, toast } from "./common.js";

class WeightedGraph{constructor(){this.a={};}edge(x,y,w){this.a[x]??=[];this.a[y]??=[];this.a[x].push({n:y,w});this.a[y].push({n:x,w});}shortest(start,end){const d={},p={},u=new Set(Object.keys(this.a));for(const n of u){d[n]=n===start?0:Infinity;p[n]=null;}while(u.size){const c=[...u].reduce((x,y)=>d[x]<=d[y]?x:y);u.delete(c);if(c===end||d[c]===Infinity)break;for(const e of this.a[c])if(u.has(e.n)&&d[c]+e.w<d[e.n]){d[e.n]=d[c]+e.w;p[e.n]=c;}}const path=[];for(let c=end;c;c=p[c])path.unshift(c);return{distance:d[end],path:path[0]===start?path:[]};}}
const graph=new WeightedGraph();graph.edge("Depot Pakal","Babat Jerawat",1.1);graph.edge("Depot Pakal","Pakal",.9);graph.edge("Babat Jerawat","Pakal",1.3);graph.edge("Babat Jerawat","Sumber Rejo",3.5);graph.edge("Pakal","Benowo",1.8);graph.edge("Pakal","Sumber Rejo",3);graph.edge("Benowo","Sumber Rejo",2.7);
const user=await requireRole("teknisi");if(!user)throw new Error("Akses dihentikan");setupPortal(user,"Teknisi Lapangan");document.getElementById("logoutBtn").onclick=logout;const map=initLeafletMap("routeMap"),layers=[];let reports=[];
function orderTasks(items){return [...items].sort((a,b)=>Number(b.severity)-Number(a.severity)||graph.shortest("Depot Pakal",a.village).distance-graph.shortest("Depot Pakal",b.village).distance);}
function renderMap(tasks){if(!map)return;layers.splice(0).forEach(x=>x.remove());const points=[LOCATIONS["Depot Pakal"]],depot=L.marker(points[0],{icon:markerIcon("Selesai")}).addTo(map).bindPopup("Depot teknisi");layers.push(depot);tasks.forEach(r=>{points.push([r.lat,r.lng]);layers.push(L.marker([r.lat,r.lng],{icon:markerIcon(r.status)}).addTo(map).bindPopup(`<strong>${escapeHTML(r.id)}</strong><br>${escapeHTML(r.address)}`));});if(points.length>1){const line=L.polyline(points,{color:"#5552d9",weight:4,dashArray:"8 8"}).addTo(map);layers.push(line);map.fitBounds(L.latLngBounds(points).pad(.25));}else map.setView(LOCATIONS["Depot Pakal"],14);}
function render(){const active=reports.filter(r=>["Ditugaskan","Menuju Lokasi"].includes(r.status)),tasks=orderTasks(active);document.getElementById("taskCount").textContent=`${tasks.length} tugas`;document.getElementById("routeBadge").textContent=`${tasks.length} titik`;document.getElementById("taskList").innerHTML=tasks.length?tasks.map((r,i)=>`<article class="task-card"><div class="task-card-head"><div><span class="section-kicker">Rute ${i+1} · ${escapeHTML(r.id)}</span><h3>${escapeHTML(r.village)} — ${escapeHTML(r.category)}</h3></div><span class="priority ${priorityClass(r.severity)}">${priorityLabel(r.severity)}</span></div><p>${escapeHTML(r.address)}<br>Status: <b>${escapeHTML(r.status)}</b></p><a class="map-link task-map-link" target="_blank" rel="noopener" href="https://www.google.com/maps?q=${r.lat},${r.lng}">Buka navigasi Google Maps</a><div class="task-actions">${r.status==="Ditugaskan"?`<button data-action="start" data-id="${r.id}">Mulai perjalanan</button>`:""}<button class="complete" data-action="complete" data-id="${r.id}">Tandai selesai</button></div></article>`).join(""):'<div class="empty-state"><span>✓</span><h3>Tidak ada tugas aktif</h3><p>Penugasan baru dari admin akan tampil di sini.</p></div>';document.querySelectorAll("[data-action]").forEach(b=>b.onclick=()=>changeStatus(b.dataset.id,b.dataset.action));let total=0,from="Depot Pakal";const stops=[from];tasks.forEach(r=>{const s=graph.shortest(from,r.village);total+=Number.isFinite(s.distance)?s.distance:0;from=r.village;stops.push(r.village);});document.getElementById("routeSummary").innerHTML=tasks.length?`<div class="route-steps">${stops.map((x,i)=>`${i?'<span class="route-arrow">›</span>':''}<span class="route-step">${escapeHTML(x)}</span>`).join("")}</div><small>Estimasi bobot graph ${total.toFixed(1)} km · urutan prioritas lalu jarak terpendek.</small>`:"<p>Rute akan muncul setelah admin menugaskan laporan.</p>";renderMap(tasks);}
async function changeStatus(id,action){try{await updateReport(id,{status:action==="start"?"Menuju Lokasi":"Selesai"});await load();toast(action==="start"?"Status diperbarui: menuju lokasi.":"Laporan ditandai selesai.");}catch(err){toast(err.message||"Status gagal diperbarui.");}}
async function load(){reports=await listReports(user);render();}
document.getElementById("refreshRouteBtn").onclick=()=>load().then(()=>toast("Rute dihitung ulang menggunakan graph wilayah."));await load();
